// Michelin Guide overlay.
//
// We bundle a dataset of the world's 1/2/3-star restaurants (src/data/michelin.json,
// generated by scripts/build-michelin-data.mjs). On a restaurant detail page we
// look the place up by name + city and, when it matches, surface its star count,
// a link to its Michelin Guide page, and override the displayed cuisine + price.
//
// The dataset has NO Google place id and NO coordinates — only name/city/country/
// address. Matching is therefore name + city based. `(name, city)` is unique
// across the sheet, so confirming the city disambiguates same-name restaurants in
// different cities (e.g. "Jamavar" in London vs Dubai) and keeps matching strict
// (no false positives on a same-name non-starred place elsewhere).

import { priceLevelToString } from './places';

export interface MichelinInfo {
  name: string;
  city: string;
  country: string;
  /** 1, 2, or 3 Michelin stars. */
  stars: 1 | 2 | 3;
  /** Price tier 1-4 (count of currency symbols in the source). */
  priceTier: number;
  /** Cuisine string, possibly comma-separated ("Modern Cuisine, Creative"). */
  cuisine: string;
  /** Michelin Guide page URL. */
  guideUrl: string;
  /** Awarded a Michelin Green Star (sustainability). */
  greenStar: boolean;
}

// Compact on-disk record shape (see scripts/build-michelin-data.mjs).
interface RawRecord {
  n: string;
  c: string;
  co: string;
  s: 1 | 2 | 3;
  pt: number;
  cu: string;
  u: string;
  g?: boolean;
}

// Lowercase, strip diacritics, drop punctuation, collapse whitespace. Used for
// both restaurant-name and city comparisons so accents ("Krusa", "L'Atelier")
// and punctuation differences between Google and Michelin don't block a match.
export function normalize(s: string): string {
  return (s || '')
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '') // combining diacritical marks
    .toLowerCase()
    .replace(/&/g, ' and ')
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
}

type Index = Map<string, MichelinInfo[]>;

let indexPromise: Promise<Index> | null = null;

function toInfo(r: RawRecord): MichelinInfo {
  return {
    name: r.n,
    city: r.c,
    country: r.co,
    stars: r.s,
    priceTier: r.pt,
    cuisine: r.cu,
    guideUrl: r.u,
    greenStar: !!r.g,
  };
}

// Lazily load + index the dataset. The JSON is a dynamic import so it is
// code-split out of the main bundle and only fetched the first time a detail
// page performs a lookup.
function loadIndex(): Promise<Index> {
  if (!indexPromise) {
    indexPromise = import('../data/michelin.json')
      .then((mod) => {
        const records = ((mod as { default?: RawRecord[] }).default
          || (mod as unknown as RawRecord[])) as RawRecord[];
        const index: Index = new Map();
        for (const r of records) {
          const key = normalize(r.n);
          if (!key) continue;
          const info = toInfo(r);
          const bucket = index.get(key);
          if (bucket) bucket.push(info);
          else index.set(key, [info]);
        }
        return index;
      })
      .catch((err) => {
        console.error('[Michelin] failed to load dataset', err);
        return new Map() as Index;
      });
  }
  return indexPromise;
}

// True when the candidate's city is present in the place's address. We compare
// against a normalized address so "New York" matches "...New York, NY, USA" and
// "Paris" matches "...Paris, France". Substring containment keeps multi-word
// cities ("San Sebastian", "Hong Kong") intact.
function cityMatchesAddress(city: string, normalizedAddress: string): boolean {
  const c = normalize(city);
  if (!c) return false;
  if (normalizedAddress.includes(c)) return true;
  // Some Michelin "City" values are districts/areas; fall back to matching the
  // first token (e.g. "Krusa") if the whole string isn't present.
  const first = c.split(' ')[0];
  return first.length >= 4 && normalizedAddress.includes(first);
}

/**
 * Find the Michelin record for a Google place by name + location. Strict: the
 * name must match (normalized) AND the record's city must appear in the place's
 * address. Returns null when there's no confident match.
 *
 * @param name    Google place display name.
 * @param address Best available address (prefer fullAddress over short address).
 */
export async function findMichelinMatch(
  name: string,
  address: string,
): Promise<MichelinInfo | null> {
  const key = normalize(name);
  if (!key) return null;
  const index = await loadIndex();
  const candidates = index.get(key);
  if (!candidates || candidates.length === 0) return null;

  const normAddr = normalize(address);

  // Single candidate: still require city confirmation so a same-name non-starred
  // place in another city doesn't get tagged. If we have no address to check
  // against, accept the unique-name single candidate (best effort).
  if (candidates.length === 1) {
    if (!normAddr) return candidates[0];
    return cityMatchesAddress(candidates[0].city, normAddr) ? candidates[0] : null;
  }

  // Multiple same-name candidates (different cities): pick the one whose city
  // appears in the address.
  for (const cand of candidates) {
    if (cityMatchesAddress(cand.city, normAddr)) return cand;
  }
  return null;
}

/** Render the Michelin price tier using the app's standard `$`-tier formatter. */
export function michelinPriceDisplay(info: MichelinInfo): string {
  return priceLevelToString(info.priceTier);
}
